CREATE TYPE "AccountType" AS ENUM ('ASSET', 'LIABILITY', 'EQUITY', 'INCOME', 'EXPENSE');
CREATE TYPE "AccountingPeriodStatus" AS ENUM ('OPEN', 'CLOSED');
CREATE TABLE "ChartOfAccount" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "type" "AccountType" NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "ChartOfAccount_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ChartOfAccount_organizationId_code_key" ON "ChartOfAccount"("organizationId", "code"); ALTER TABLE "ChartOfAccount" ADD CONSTRAINT "ChartOfAccount_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "AccountingPeriod" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "startDate" DATE NOT NULL, "endDate" DATE NOT NULL, "status" "AccountingPeriodStatus" NOT NULL DEFAULT 'OPEN', CONSTRAINT "AccountingPeriod_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "AccountingPeriod_organizationId_startDate_endDate_key" ON "AccountingPeriod"("organizationId", "startDate", "endDate"); ALTER TABLE "AccountingPeriod" ADD CONSTRAINT "AccountingPeriod_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "JournalEntry" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "periodId" TEXT, "entryDate" DATE NOT NULL, "reference" TEXT NOT NULL, "description" TEXT NOT NULL, "sourceType" TEXT NOT NULL, "sourceId" TEXT NOT NULL, CONSTRAINT "JournalEntry_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "JournalEntry_organizationId_sourceType_sourceId_key" ON "JournalEntry"("organizationId", "sourceType", "sourceId"); CREATE INDEX "JournalEntry_organizationId_entryDate_idx" ON "JournalEntry"("organizationId", "entryDate"); ALTER TABLE "JournalEntry" ADD CONSTRAINT "JournalEntry_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "JournalEntry" ADD CONSTRAINT "JournalEntry_periodId_fkey" FOREIGN KEY ("periodId") REFERENCES "AccountingPeriod"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "JournalLine" ("id" TEXT NOT NULL, "journalEntryId" TEXT NOT NULL, "accountId" TEXT NOT NULL, "debit" DECIMAL(14,2) NOT NULL DEFAULT 0, "credit" DECIMAL(14,2) NOT NULL DEFAULT 0, CONSTRAINT "JournalLine_pkey" PRIMARY KEY ("id")); ALTER TABLE "JournalLine" ADD CONSTRAINT "JournalLine_journalEntryId_fkey" FOREIGN KEY ("journalEntryId") REFERENCES "JournalEntry"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "JournalLine" ADD CONSTRAINT "JournalLine_accountId_fkey" FOREIGN KEY ("accountId") REFERENCES "ChartOfAccount"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
